/*
 * Main computational kernel. The whole function will be timed,
 * including the call and return.
 *
 * Optimizations compared to the original kernel:
 *  - Fuse the beta scaling and rank-2k update so each C[i][j] is
 *    loaded and stored exactly once.
 *  - Interchange the (j,k) loops so that k is the innermost loop,
 *    giving unit-stride (row-major) access to A and B and exposing
 *    efficient SIMD/vectorization.
 *  - For each row i, precompute alpha-scaled copies of row i of A and B
 *    (alphaA[k] = alpha*A[i][k], alphaB[k] = alpha*B[i][k]) and reuse
 *    them across all j in that row, reducing the number of
 *    multiplications involving alpha.
 *  - Tile the outer i-loop and the inner k-reduction loop to improve
 *    cache locality on large problems.
 *
 * Semantics are preserved:
 *  For all 0 <= j <= i < N,
 *    C[i][j] = beta * C[i][j]
 *              + alpha * sum_{k=0..M-1} ( A[j][k] * B[i][k]
 *                                        + B[j][k] * A[i][k] )
 *  and entries with j > i are left unchanged.
 */
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;

  /* Create explicit restrict-qualified row-major views to help the
     compiler with alias analysis and vectorization. */
  DATA_TYPE (*restrict C_)[n] = C;
  DATA_TYPE (*restrict A_)[m] = A;
  DATA_TYPE (*restrict B_)[m] = B;

  /* PolyBench loop bounds (typically equal to n and m). */
  const int nPB = _PB_N;
  const int mPB = _PB_M;

  /* Local copies of scalars for slightly cheaper access. */
  const DATA_TYPE alpha_local = alpha;
  const DATA_TYPE beta_local  = beta;

  /* Temporary buffers holding alpha-scaled copies of row i of A and B.
     Size is O(M), so the extra memory footprint is small. */
  DATA_TYPE alphaA[mPB];
  DATA_TYPE alphaB[mPB];

  /* Tile sizes chosen empirically for modern x64 CPUs.
     - TILE_I controls how many rows of C are worked on before moving on.
     - TILE_K controls the k-block size for the inner product. */
  const int TILE_I = 64;
  const int TILE_K = 256;

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  /* Tile the i-dimension for better cache behavior on very large matrices. */
  for (int ii = 0; ii < nPB; ii += TILE_I)
  {
    int i_end = ii + TILE_I;
    if (i_end > nPB)
      i_end = nPB;

    for (i = ii; i < i_end; ++i)
    {
      /* Precompute alphaA[k] = alpha * A[i][k] and
         alphaB[k] = alpha * B[i][k] once per (i,k).
         Access pattern is unit-stride in k, ideal for SIMD. */
#pragma GCC ivdep
      for (k = 0; k < mPB; ++k)
      {
        DATA_TYPE Aik = A_[i][k];
        DATA_TYPE Bik = B_[i][k];
        alphaA[k] = alpha_local * Aik;
        alphaB[k] = alpha_local * Bik;
      }

      /* Update only the lower triangular part (j <= i) of row i of C. */
      for (j = 0; j <= i; ++j)
      {
        /* Fuse the original beta scaling with the subsequent update:
             C[i][j] *= beta;
             for k: C[i][j] += ...
           becomes:
             cij = beta * C[i][j];
             for k: cij += ...
             C[i][j] = cij;
           so C[i][j] is loaded/stored exactly once. */
        DATA_TYPE cij = beta_local * C_[i][j];

        /* Tiled reduction over k to improve cache reuse of alphaA/alphaB
           and of the j-th rows of A and B for large M. */
        for (int kk = 0; kk < mPB; kk += TILE_K)
        {
          int k_end = kk + TILE_K;
          if (k_end > mPB)
            k_end = mPB;

          /* Inner k-loop: all arrays are accessed with unit stride in k:
               A_[j][k], B_[j][k], alphaA[k], alphaB[k]
             This is highly vectorizable. */
#pragma GCC ivdep
          for (k = kk; k < k_end; ++k)
          {
            cij += A_[j][k] * alphaB[k] + B_[j][k] * alphaA[k];
          }
        }

        C_[i][j] = cij;
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_syr2k (n, m,
		alpha, beta,
		POLYBENCH_ARRAY(C),
		POLYBENCH_ARRAY(A),
		POLYBENCH_ARRAY(B));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(C)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);

  return 0;
