/* syr2k.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "syr2k.h"

/* Tunable tiling parameters for the optimized kernel.
 *
 * These tile sizes are chosen for a modern x86-64 CPU with large caches.
 * They do not need to divide N or M exactly; edge iterations are handled
 * explicitly in the loops.
 *
 * You can experiment with these values at compile time, e.g.:
 *   -DSYR2K_TILE_I=64 -DSYR2K_TILE_J=64 -DSYR2K_TILE_K=128
 */
#ifndef SYR2K_TILE_I
# define SYR2K_TILE_I 32
#endif

#ifndef SYR2K_TILE_J
# define SYR2K_TILE_J 32
#endif

#ifndef SYR2K_TILE_K
# define SYR2K_TILE_K 64
#endif


/* Array initialization. */
static
void init_array(int n, int m,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++) {
      A[i][j] = (DATA_TYPE) ((i*j+1)%n) / n;
      B[i][j] = (DATA_TYPE) ((i*j+2)%m) / m;
    }
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
      C[i][j] = (DATA_TYPE) ((i*j+3)%n) / m;
    }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(C,N,N,n,n))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("C");
  for (i = 0; i < n; i++)
    for (j = 0; j < n; j++) {
	if ((i * n + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, C[i][j]);
    }
  POLYBENCH_DUMP_END("C");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_syr2k[[gnu::flatten, gnu::noinline]](int n, int m,
		  DATA_TYPE alpha,
		  DATA_TYPE beta,
		  DATA_TYPE POLYBENCH_2D(C,N,N,n,n),
		  DATA_TYPE POLYBENCH_2D(A,N,M,n,m),
		  DATA_TYPE POLYBENCH_2D(B,N,M,n,m))
{
  int i, j, k;
  int ii, jj, kk;

  /* Tiled, locality-optimized version of the SYR2K kernel.
   *
   * Mathematical operation (UPLO='L', TRANS='N'):
   *   For 0 <= j <= i < n:
   *     C[i,j] = beta * C[i,j]
   *              + alpha * sum_{k=0..m-1} ( A[j,k]*B[i,k] + B[j,k]*A[i,k] )
   *
   * Key optimizations compared to the original code:
   *   - Fuse the separate scaling and update loops so that each C[i,j] is
   *     loaded and stored exactly once.
   *   - Change loop order to make the reduction over k innermost. With
   *     row-major layout this gives stride-1 access in k for all four
   *     arrays A[j,*], B[j,*], A[i,*], B[i,*], which is friendly to caches
   *     and auto-vectorization.
   *   - Factor 'alpha' outside the k-summation: we accumulate
   *         sum_k (A[j,k]*B[i,k] + B[j,k]*A[i,k])
   *     and multiply by alpha once per (i,j) at the end. This reduces the
   *     number of multiplications by alpha from O(n^2*m) to O(n^2).
   *   - Tile the i and j dimensions to improve locality on C, and (optionally)
   *     tile k to improve cache reuse on A and B. Edge tiles are handled
   *     explicitly, so no assumptions about divisibility are made.
   *   - Use row pointers (Ai, Bi, Aj, Bj) to reduce address arithmetic in
   *     the innermost loops.
   *
   * Only the lower triangular part (j <= i) is updated, exactly as in the
   * original kernel. Entries with j > i remain untouched.
   */

//BLAS PARAMS
//UPLO  = 'L'
//TRANS = 'N'
//A is NxM
//B is NxM
//C is NxN
#pragma scop
  for (ii = 0; ii < _PB_N; ii += SYR2K_TILE_I) {
    int i_end = ii + SYR2K_TILE_I;
    if (i_end > _PB_N)
      i_end = _PB_N;

    /* Process a tile of rows [ii, i_end) of C (and corresponding rows of A,B). */
    for (i = ii; i < i_end; ++i) {
      /* Row pointers for A[i][*] and B[i][*]; reused for all j in this row. */
      DATA_TYPE *restrict Ai = A[i];
      DATA_TYPE *restrict Bi = B[i];

      /* j is restricted to the lower triangle: 0 <= j <= i.
       * We additionally tile j to work on small bands of the lower triangle.
       */
      for (jj = 0; jj <= i; jj += SYR2K_TILE_J) {
        int j_end = jj + SYR2K_TILE_J;
        if (j_end > i + 1)
          j_end = i + 1; /* ensure j <= i */

        for (j = jj; j < j_end; ++j) {
          /* Load and scale C[i][j] once. It will stay in a register until
           * the full reduction over k is complete.
           */
          DATA_TYPE cij = C[i][j] * beta;

          /* Accumulator for the symmetric rank-2k contribution. We do *not*
           * multiply by alpha here; instead, we factor alpha outside the
           * k-loop and apply it once per (i,j) at the end.
           */
          DATA_TYPE sum = (DATA_TYPE)0;

          /* Row pointers for A[j][*] and B[j][*]; reused across k. */
          DATA_TYPE *restrict Aj = A[j];
          DATA_TYPE *restrict Bj = B[j];

          /* Optional blocking in k to improve cache reuse for very large m.
           * The inner-most k loop has unit-stride accesses:
           *   Aj[k], Bj[k], Ai[k], Bi[k]
           * which is ideal for SIMD and hardware prefetching.
           */
          for (kk = 0; kk < _PB_M; kk += SYR2K_TILE_K) {
            int k_end = kk + SYR2K_TILE_K;
            if (k_end > _PB_M)
              k_end = _PB_M;

            for (k = kk; k < k_end; ++k) {
              DATA_TYPE a_jk = Aj[k];
              DATA_TYPE b_jk = Bj[k];
              DATA_TYPE a_ik = Ai[k];
              DATA_TYPE b_ik = Bi[k];

              /* Accumulate the symmetric rank-2k contribution for this (i,j). */
              sum += a_jk * b_ik + b_jk * a_ik;
            }
          }

          /* Finalize C[i][j] for this (i,j) pair. */
          C[i][j] = cij + alpha * sum;
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;
  int m = M;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,N,N,n,n);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,N,M,n,m);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,N,M,n,m);

  /* Initialize array(s). */
  init_array (n, m, &alpha, &beta,
	      POLYBENCH_ARRAY(C),
