  /* PolyBench provides possibly instrumented loop bounds via _PB_N/_PB_M.
     We use them for iteration counts but keep the original 'n'/'m' as the
     second dimension sizes of the VLA pointers. */
  const int n_it = _PB_N;
  const int m_it = _PB_M;

  /* Create local restrict-qualified aliases to help the compiler with
     alias analysis and vectorization. */
  DATA_TYPE (* restrict C_)[n] = C;
  DATA_TYPE (* restrict A_)[m] = A;
  DATA_TYPE (* restrict B_)[m] = B;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

#pragma scop
  /* Parallelize outer loop over independent rows of C.
     Each iteration of 'i' writes to a distinct row C[i][:] and reads from
     disjoint A[i][:], B[i][:]; A and B are otherwise read-only. */
#ifdef _OPENMP
#pragma omp parallel for schedule(static) private(j, k)
#endif
  for (i = 0; i < n_it; i++)
  {
    /* Temporary buffers for the alpha-scaled copy of row i of A and B.
       Size is O(M); they live in the stack frame of each iteration (and,
       under OpenMP, of each thread), so there are no data races. */
    DATA_TYPE alphaA[m_it];
    DATA_TYPE alphaB[m_it];

    /* Precompute alpha * A[i,k] and alpha * B[i,k] once per row i.
       Accesses are contiguous in k for both A and B (row-major). */
    for (k = 0; k < m_it; ++k)
    {
      DATA_TYPE a_ik = A_[i][k];
      DATA_TYPE b_ik = B_[i][k];
      alphaA[k] = alpha_ * a_ik;
      alphaB[k] = alpha_ * b_ik;
    }

    /* Update only the lower triangular part: 0 <= j <= i.
       C[i][j] is kept in a scalar accumulator across the full k-reduction,
       then written back exactly once. */
    for (j = 0; j <= i; ++j)
    {
      DATA_TYPE cij = beta_ * C_[i][j];

      /* Inner product over k.
         All four arrays accessed here have unit stride in k:
           - A_[j][k], B_[j][k] : row j of A and B
           - alphaA[k], alphaB[k] : 1D temporaries
         which is friendly to the hardware prefetcher and SIMD. */
      for (k = 0; k < m_it; ++k)
      {
        cij += A_[j][k] * alphaB[k] +
               B_[j][k] * alphaA[k];
      }

      C_[i][j] = cij;
    }
    /* For j > i, C_[i][j] is untouched, exactly as in the original code. */
  }
#pragma endscop

